public class AccessChecker{static String classifyAccess(String m,String c){if(c.equals("SAME_CLASS"))return"ALLOWED";if(m.equals("private"))return"DENIED";if(m.equals("default"))return c.equals("SAME_PACKAGE")?"ALLOWED":"DENIED";if(m.equals("protected"))return c.equals("DIFFERENT_PACKAGE")?"DENIED":"ALLOWED";return"ALLOWED";}static String summarizeByModifier(String[][] a){StringBuilder r=new StringBuilder();for(String m:new String[]{"private","default","protected","public"}){int y=0,n=0;for(String[] x:a)if(x[0].equals(m)){if(classifyAccess(x[0],x[1]).equals("ALLOWED"))y++;else n++;}r.append(m+": "+y+" allowed / "+n+" denied | ");}return r.toString();}}